import { BookingPage } from './BookingPage.tsx';
import { ConfirmationPage } from './ConfirmationPage.tsx';
import { NotFoundCard } from './ui.tsx';

export function App() {
  const path = location.pathname;
  const bookingId = /^\/bookings\/([0-9a-f-]{36})$/.exec(path)?.[1];
  return (
    <>
      <header className="mx-auto flex max-w-3xl items-center justify-between px-4 py-5">
        <a href="/" className="text-xl font-bold">Codeyoung</a>
        <a href="/mentors" className="text-sm font-medium underline-offset-4 hover:underline">Our mentors</a>
      </header>
      <main className="px-4 pb-12">
        {path === '/' ? <BookingPage /> : bookingId ? <ConfirmationPage id={bookingId} /> : <NotFoundCard title="We couldn't find that page." />}
      </main>
    </>
  );
}
import type { ReactNode } from 'react';
import { cityName, formatDateWithYear, formatTime } from '../shared/time.ts';

export function Card({ children }: { children: ReactNode }) {
  return <div className="mx-auto w-full max-w-[440px] rounded-card border border-line bg-white p-8 shadow-card">{children}</div>;
}

/** Every primary button: full width, 14px bold, 16px vertical padding. */
export const primaryButton = 'block w-full rounded-cta bg-brand py-4 text-center text-sm font-bold text-ink';

export function NotFoundCard({ title }: { title: string }) {
  return (
    <Card>
      <h1 className="text-2xl font-medium">{title}</h1>
      <a href="/" className="mt-4 inline-block font-bold underline underline-offset-4">Back to the home page</a>
    </Card>
  );
}

export function CardTitle() {
  return (
    <h1 className="text-2xl font-medium">
      Book a <span className="underline decoration-brand decoration-4 underline-offset-4">FREE</span> class for your child
    </h1>
  );
}

export function Progress({ step }: { step: 1 | 2 | 3 }) {
  return (
    <div role="img" aria-label={`Step ${step} of 3`} className="mb-6 flex gap-2">
      {[1, 2, 3].map((n) => (
        <span key={n} className={`h-1 w-16 rounded-field ${n <= step ? 'bg-brand' : 'bg-line'}`} />
      ))}
    </div>
  );
}

export function DemoBanner({ now, timeZone }: { now: string; timeZone: string }) {
  const at = new Date(now);
  return (
    <p className="mx-auto mb-4 w-full max-w-[440px] rounded-field bg-brand-50 px-4 py-2 text-center text-sm">
      {`Demo clock: it's ${formatDateWithYear(at, timeZone)}, ${formatTime(at, timeZone)} in ${cityName(timeZone)}`}
    </p>
  );
}

/** Initials in a soft square, for the mentor cards. */
export function Avatar({ name }: { name: string }) {
  const initials = name.split(/\s+/).map((word) => word[0]).slice(0, 2).join('');
  return (
    <span aria-hidden="true" className="flex size-12 shrink-0 items-center justify-center rounded-cta bg-brand-100 font-bold">
      {initials}
    </span>
  );
}
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useState } from 'react';
import { ApiError, createBooking, getSlots } from './api.ts';
import { initialTimeZone } from './booking.ts';

function readSavedZone(): string | null {
  try {
    return localStorage.getItem('tz');
  } catch {
    return null; // storage blocked: fall back to the device zone
  }
}

export function useTimeZone() {
  const deviceTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const [timeZone, setZone] = useState(() => initialTimeZone(readSavedZone(), deviceTimeZone));
  const setTimeZone = (tz: string) => {
    setZone(tz);
    try {
      localStorage.setItem('tz', tz);
    } catch {
      // storage blocked: the choice still holds for this visit
    }
  };
  return { timeZone, setTimeZone, deviceTimeZone };
}

export function useSlots() {
  return useQuery({ queryKey: ['slots'], queryFn: getSlots, refetchInterval: 60_000 });
}

export function useBookSlot(onUnavailable: (startsAt: string) => void) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: createBooking,
    onSuccess: ({ booking }) => location.assign('/bookings/' + booking.id),
    onError: (error, variables) => {
      if (error instanceof ApiError && error.status === 409) {
        void queryClient.invalidateQueries({ queryKey: ['slots'] });
        onUnavailable(variables.startsAt);
      }
    },
  });
}

// Pure booking logic for the browser: no React, no DOM, and no clock. Every day key comes from time.ts,
// because a UTC-midnight Date read with a local getter lands on the wrong day in the US.
import {
  addDays, canonicalTimeZone, formatZoneOption, isValidTimeZone, localDate, offsetMinutes, zoneAbbreviation,
  zonedTimeToInstant,
} from '../shared/time.ts';
import type { SlotDto } from '../shared/types.ts';

export const DAYS_SHOWN = 14;
export const COMMON_ZONES = ['America/Los_Angeles', 'America/Denver', 'America/Phoenix', 'America/Chicago', 'America/New_York',
  'America/Anchorage', 'Pacific/Honolulu', 'Europe/London', 'Europe/Dublin', 'Asia/Kolkata'];

export type Day = { key: string; slots: SlotDto[]; openCount: number };

/** Exactly 14 local days from today in `tz`, each holding the slots that start on it. */
export function groupIntoDays(slots: SlotDto[], tz: string, now: Date): Day[] {
  const today = localDate(now, tz);
  const days: Day[] = Array.from({ length: DAYS_SHOWN }, (_, i) => ({ key: addDays(today, i), slots: [], openCount: 0 }));
  const byKey = new Map(days.map((d) => [d.key, d]));
  for (const s of slots) {
    const day = byKey.get(localDate(new Date(s.startsAt), tz));
    if (!day) continue;
    day.slots.push(s);
    if (s.available) day.openCount++;
  }
  return days;
}

/** The day to show: the selected time's own day (it must stay on screen after a zone change), else the chosen day, else the first open one. */
export function shownDayKey(days: Day[], selected: string | null, chosenDay: string | null, tz: string): string {
  const has = (key: string) => days.some((d) => d.key === key);
  const selectedDay = selected && localDate(new Date(selected), tz);
  if (selectedDay && has(selectedDay)) return selectedDay;
  if (chosenDay && has(chosenDay)) return chosenDay;
  return (days.find((d) => d.openCount > 0) ?? days[0])!.key;
}

/** The open times closest to `target` (never `target` itself), in time order. */
export function nearestOpenTimes(slots: SlotDto[], target: string, count = 3): string[] {
  const at = new Date(target).getTime();
  return slots
    .filter((s) => s.available && new Date(s.startsAt).getTime() !== at)
    .map((s) => ({ startsAt: s.startsAt, t: new Date(s.startsAt).getTime() }))
    .sort((a, b) => Math.abs(a.t - at) - Math.abs(b.t - at) || a.t - b.t)
    .slice(0, count)
    .sort((a, b) => a.t - b.t)
    .map((s) => s.startsAt);
}

/** The closest days with an open time before and after `key`. */
export function nearestOpenDays(days: Day[], key: string): { before: Day | null; after: Day | null } {
  const open = days.filter((d) => d.openCount > 0);
  return { before: open.findLast((d) => d.key < key) ?? null, after: open.find((d) => d.key > key) ?? null };
}

/** The first day in the window whose midday offset differs from today's, with the zone names either side. */
export function clockChange(days: Day[], tz: string, now: Date): { dayKey: string; from: string; to: string } | null {
  const offset = offsetMinutes(now, tz);
  for (const { key } of days) {
    const noon = zonedTimeToInstant(key, '12:00', tz);
    if (offsetMinutes(noon, tz) !== offset) return { dayKey: key, from: zoneAbbreviation(now, tz), to: zoneAbbreviation(noon, tz) };
  }
  return null;
}

/** True on the day a clock change falls inside, where one day's times carry two zone names. */
export function dayMixesOffsets(day: Day, tz: string): boolean {
  return new Set(day.slots.map((s) => offsetMinutes(new Date(s.startsAt), tz))).size > 1;
}

export function sameZone(a: string, b: string): boolean {
  return canonicalTimeZone(a) === canonicalTimeZone(b);
}

type ZoneOption = { value: string; label: string; group: 'common' | 'all' };

// ponytail: one-entry cache keyed by zone and UTC hour; zoneOptions builds ~840 formatters (~30 ms) and the page re-renders on every state change
let last: { key: string; options: ZoneOption[] } | undefined;

/** One option per real zone, common zones first. The option for `current` carries `current`'s own spelling, or the select shows nothing. */
export function zoneOptions(current: string, now: Date): ZoneOption[] {
  const key = `${current}|${Math.floor(now.getTime() / 3_600_000)}`; // the hour keeps offset labels fresh across a clock change
  if (last?.key !== key) last = { key, options: buildZoneOptions(current, now) };
  return last.options;
}

function buildZoneOptions(current: string, now: Date): ZoneOption[] {
  const currentZone = canonicalTimeZone(current);
  const seen = new Set<string>();
  const options: ZoneOption[] = [];
  const add = (tz: string, group: 'common' | 'all') => {
    const zone = canonicalTimeZone(tz);
    if (seen.has(zone)) return; // 'Asia/Kolkata' and 'Asia/Calcutta' are one zone
    seen.add(zone);
    const value = zone === currentZone ? current : tz;
    options.push({ value, label: formatZoneOption(now, value), group });
  };
  for (const tz of COMMON_ZONES) add(tz, 'common');
  for (const tz of Intl.supportedValuesOf('timeZone')) add(tz, 'all');
  // ICU's list lacks 'UTC' (a US browser behind UTC reports it), and can lack the exact zone a device reports
  if (!seen.has(currentZone)) options.unshift({ value: current, label: formatZoneOption(now, current), group: 'common' });
  return options;
}

/** The stored zone when it is still a real one, else the device's, else UTC, so a junk zone never reaches the Intl calls below. */
export function initialTimeZone(stored: string | null, device: string): string {
  if (stored && isValidTimeZone(stored)) return stored;
  return isValidTimeZone(device) ? device : 'UTC';
}

export type Details = { parentName: string; parentEmail: string; childName: string };
export type FlowState = {
  step: 'details' | 'time'; details: Details; chosenDay: string | null; selected: string | null; unavailable: string | null;
};
export type FlowAction =
  | { type: 'detailsSubmitted'; details: Details } | { type: 'back' } | { type: 'daySelected'; dayKey: string }
  | { type: 'slotSelected'; startsAt: string } | { type: 'slotUnavailable'; startsAt: string };

export const initialFlow: FlowState = {
  step: 'details', details: { parentName: '', parentEmail: '', childName: '' }, chosenDay: null, selected: null, unavailable: null,
};

export function flowReducer(state: FlowState, action: FlowAction): FlowState {
  switch (action.type) {
    case 'detailsSubmitted': return { ...state, step: 'time', details: action.details };
    case 'back': return { ...state, step: 'details' };
    case 'daySelected': return { ...state, chosenDay: action.dayKey, selected: null };
    case 'slotSelected': return { ...state, selected: action.startsAt, unavailable: null };
    case 'slotUnavailable': return { ...state, selected: null, unavailable: action.startsAt };
  }
}
  expect(calcutta.slice(0, 10).map((o) => o.group)).toEqual(Array(10).fill('common'));
  expect(calcutta.filter((o) => sameZone(o.value, 'Asia/Kolkata')).map((o) => [o.value, o.label])).toEqual([['Asia/Calcutta', 'Kolkata (GMT+5:30)']]);
  expect(zoneOptions('Asia/Kolkata', NOW).filter((o) => sameZone(o.value, 'Asia/Kolkata')).map((o) => o.value)).toEqual(['Asia/Kolkata']);
  expect(calcutta.find((o) => o.value === 'Europe/London')!.label).toBe('London (GMT+1)');
});

// the select goes blank unless one option's value is the current zone, whichever way ICU spells it or the list omits it
test('zoneOptions returns the same array for the same zone and hour, and a fresh one when either changes', () => {
  const options = zoneOptions('Europe/London', NOW);
  expect(zoneOptions('Europe/London', new Date(NOW.getTime() + 60_000))).toBe(options);
  expect(zoneOptions('Europe/London', new Date(NOW.getTime() + 3_600_000))).not.toBe(options);
  expect(zoneOptions('America/New_York', NOW).find((o) => o.value === 'America/New_York')).toBeDefined();
});

test.each(['UTC', 'Europe/Paris', 'Europe/Kiev', 'Asia/Calcutta'])('zoneOptions(%s) has one option whose value is the current zone, and no zone twice', (current) => {
  const options = zoneOptions(current, NOW);
  expect(options.filter((o) => o.value === current)).toHaveLength(1);
  const zones = options.map((o) => new Intl.DateTimeFormat('en', { timeZone: o.value }).resolvedOptions().timeZone);
  expect(new Set(zones).size).toBe(zones.length);
});

test('initialTimeZone and sameZone', () => {
  expect(initialTimeZone('Europe/London', 'America/New_York')).toBe('Europe/London');
  expect(initialTimeZone('Mars/Base', 'America/New_York')).toBe('America/New_York');
  expect(initialTimeZone(null, 'America/New_York')).toBe('America/New_York');
  expect(initialTimeZone(null, 'Mars/Base')).toBe('UTC');
  expect(sameZone('Asia/Kolkata', 'Asia/Calcutta')).toBe(true);
});

test('flowReducer keeps details through a 409 and clears the selection', () => {
  const details = { parentName: 'Asha Patel', parentEmail: 'asha@example.com', childName: 'Rohan' };
  let s = flowReducer(initialFlow, { type: 'detailsSubmitted', details });
  expect(s.step).toBe('time');
  s = flowReducer(s, { type: 'slotSelected', startsAt: '2026-10-27T16:00:00Z' });
  s = flowReducer(s, { type: 'slotUnavailable', startsAt: '2026-10-27T16:00:00Z' });
  expect(s).toMatchObject({ step: 'time', details, selected: null, unavailable: '2026-10-27T16:00:00Z' });
  expect(flowReducer(s, { type: 'slotSelected', startsAt: '2026-10-27T17:00:00Z' })).toMatchObject({ selected: '2026-10-27T17:00:00Z', unavailable: null });
  expect(flowReducer(s, { type: 'daySelected', dayKey: '2026-10-28' })).toMatchObject({ chosenDay: '2026-10-28', selected: null });
  expect(flowReducer(s, { type: 'back' })).toMatchObject({ step: 'details', details });
});
import { expect, test } from 'vitest';
import { addDays } from '../shared/time.ts';
import type { SlotDto } from '../shared/types.ts';
import {
  clockChange, dayMixesOffsets, flowReducer, groupIntoDays, initialFlow, initialTimeZone, nearestOpenDays,
  nearestOpenTimes, sameZone, shownDayKey, zoneOptions,
} from './booking.ts';

const NOW = new Date('2026-10-20T12:00:00Z');
const slot = (startsAt: string, available = true): SlotDto => ({ startsAt, available });

test('groups into exactly 14 local days starting today, ignoring later slots', () => {
  const days = groupIntoDays([slot('2026-10-20T15:00:00Z'), slot('2026-11-02T23:00:00Z'), slot('2026-11-03T10:00:00Z')], 'Europe/London', NOW);
  expect(days.map((d) => d.key)).toEqual(Array.from({ length: 14 }, (_, i) => addDays('2026-10-20', i)));
  expect(days.at(-1)!.slots.map((s) => s.startsAt)).toEqual(['2026-11-02T23:00:00Z']);
});

test('each repeated 1:00 AM lands on its own change day', () => {
  const london = groupIntoDays([slot('2026-10-25T00:00:00Z'), slot('2026-10-25T01:00:00Z')], 'Europe/London', NOW);
  expect(london.find((d) => d.key === '2026-10-25')!.slots).toHaveLength(2);
